          'Можете да промените имейл адреса си и ние ще изпратим имейл за потвърждение за промяна.',
      'bn':
          'আপনি আপনার ইমেল ঠিকানা পরিবর্তন করতে পারেন, এবং আমরা পরিবর্তন করার জন্য একটি নিশ্চিতকরণ ইমেল করব৷',
      'bs':
          'Možete promijeniti svoju adresu e-pošte, a mi ćemo poslati e-poruku s potvrdom za promjenu.',
      'ca':
          'Podeu canviar la vostra adreça de correu electrònic i us enviarem un correu electrònic de confirmació per canviar-lo.',
      'cs':
          'Svou e-mailovou adresu můžete změnit a my vám zašleme potvrzovací e-mail ke změně.',
      'da':
          'Du kan ændre din e-mailadresse, og vi sender en bekræftelses-e-mail for at ændre.',
      'de':
          'Sie können Ihre E-Mail-Adresse ändern und wir senden Ihnen zur Änderung eine Bestätigungs-E-Mail.',
      'el':
          'Μπορείτε να αλλάξετε τη διεύθυνση email σας και θα σας στείλουμε ένα email επιβεβαίωσης για αλλαγή.',
      'es':
          'Puede cambiar su dirección de correo electrónico y le enviaremos un correo electrónico de confirmación para cambiarla.',
      'et':
          'Saate oma e-posti aadressi muuta ja me saadame muutmise kohta kinnitusmeili.',
      'eu':
          'Zure helbide elektronikoa alda dezakezu eta aldatzeko berrespen-mezu bat bidaliko dizugu.',
      'fa':
          'می‌توانید آدرس ایمیل خود را تغییر دهید، و ما یک ایمیل تأیید برای تغییر ارسال می‌کنیم.',
      'fi':
          'Voit vaihtaa sähköpostiosoitteesi, niin lähetämme muutoksesta vahvistussähköpostin.',
