          'તમે તમારું ઇમેઇલ સરનામું બદલી શકો છો, અને અમે બદલવા માટે પુષ્ટિકરણ ઇમેઇલ કરીશું.',
      'hi':
          'आप अपना ईमेल पता बदल सकते हैं, और हम आपको परिवर्तन हेतु एक पुष्टिकरण ईमेल भेजेंगे।',
