      'kn':
          'ನಿಮ್ಮ ಇಮೇಲ್ ವಿಳಾಸವನ್ನು ನೀವು ಬದಲಾಯಿಸಬಹುದು ಮತ್ತು ಬದಲಾಯಿಸಲು ನಾವು ದೃಢೀಕರಣ ಇಮೇಲ್ ಮಾಡುತ್ತೇವೆ.',
