          'Можете да ја промените вашата адреса на е-пошта, а ние ќе испратиме е-пошта за потврда за промена.',
      'ml':
          'നിങ്ങൾക്ക് നിങ്ങളുടെ ഇമെയിൽ വിലാസം മാറ്റാം, മാറ്റാൻ ഞങ്ങൾക്ക് ഒരു സ്ഥിരീകരണ ഇമെയിൽ ലഭിക്കും.',
      'mn':
          'Та имэйл хаягаа өөрчлөх боломжтой бөгөөд бид өөрчлөхийг баталгаажуулах имэйл илгээх болно.',
      'mr':
          'तुम्ही तुमचा ईमेल पत्ता बदलू शकता आणि आम्ही बदलण्यासाठी पुष्टीकरण ईमेल करू.',
      'ms':
          'Anda boleh menukar alamat e-mel anda dan kami akan menukar e-mel pengesahan untuk ditukar.',
      'my':
          'သင့်အီးမေးလ်လိပ်စာကို သင်ပြောင်းနိုင်ပြီး ပြောင်းလဲရန် အတည်ပြုအီးမေးလ်တစ်ခု ပေးပါမည်။',
      'ne':
          'तपाईं आफ्नो इमेल ठेगाना परिवर्तन गर्न सक्नुहुन्छ, र हामी परिवर्तन गर्न पुष्टिकरण इमेल गर्नेछौं।',
      'nl':
          'U kunt uw e-mailadres wijzigen, waarna wij een bevestigingsmail sturen om dit te wijzigen.',
      'no':
          'Du kan endre e-postadressen din, så sender vi en bekreftelses-e-post for endring.',
      'or':
          'ଆପଣ ଆପଣଙ୍କର ଇମେଲ୍ ଠିକଣା ପରିବର୍ତ୍ତନ କରିପାରିବେ, ଏବଂ ଆମେ ପରିବର୍ତ୍ତନ କରିବାକୁ ଏକ ନିଶ୍ଚିତକରଣ ଇମେଲ୍ କରିବୁ |',
      'pa':
          'ਤੁਸੀਂ ਆਪਣਾ ਈਮੇਲ ਪਤਾ ਬਦਲ ਸਕਦੇ ਹੋ, ਅਤੇ ਅਸੀਂ ਬਦਲਣ ਲਈ ਇੱਕ ਪੁਸ਼ਟੀਕਰਨ ਈਮੇਲ ਭੇਜਾਂਗੇ।',
      'pl':
          'Możesz zmienić swój adres e-mail, a my wyślemy wiadomość e-mail z potwierdzeniem zmiany.',
      'pt':
          'Você pode alterar seu endereço de e-mail e enviaremos um e-mail de confirmação para alterar.',
