      'sd':
          'توھان پنھنجي اي ميل پتي کي تبديل ڪري سگھو ٿا، ۽ اسان کي تبديل ڪرڻ لاء ھڪ تصديق واري اي ميل ڪنداسين.',
      'si':
          'ඔබට ඔබගේ විද්‍යුත් තැපැල් ලිපිනය වෙනස් කළ හැක, අපි වෙනස් කිරීමට තහවුරු කිරීමේ විද්‍යුත් තැපෑලක් එවන්නම්.',
