          'At iEvangelize, we harness the power of technology to inspire, equip, and mobilize believers to fulfill The Great Commission in their everyday lives. Our mission is to provide the tools and resources you need to confidently share the Gospel and make a lasting impact. Together, we can reach every corner of the world with the message and pwoer of the Gospel. iEvangelize exists to help you take the next step in bringing light to your world—because it takes all of us to reach everyone.',
      'am':
          'የእኛ ተልእኮ አማኞችን ማሰባሰብ እና ታላቁን ተልእኮ በዓለማቸው እንዲፈጽሙ አስፈላጊ መሳሪያዎችን ማስታጠቅ ነው። ወንጌልን ለሁሉም ለማድረስ ሁላችንም ያስፈልጋል፣ እና ኢቫንጀሊዝም አማኞች ይህን እንዲያደርጉ ለመርዳት አለ።',
      'ar':
          'مهمتنا هي تعبئة المؤمنين وتزويدهم بالأدوات اللازمة لتحقيق المأمورية العظمى في عالمهم. يتطلب الأمر منا جميعًا أن نصل إلى الجميع بالإنجيل، وiEvangelize موجود لمساعدة المؤمنين على القيام بذلك.',
      'be':
          'Наша місія складаецца ў тым, каб мабілізаваць вернікаў і даць ім неабходныя прылады для выканання Вялікага даручэння ў іх свеце. Усім нам трэба, каб данесці да кожнага Евангелле, і iEvangelize існуе, каб дапамагчы вернікам зрабіць гэта.',
      'bg':
          'Нашата мисия е да мобилизираме и оборудваме вярващите с необходимите инструменти, за да изпълнят Голямото поръчение в техния свят. Необходимо е всички ние да достигнем до всички с Евангелието и iEvangelize съществува, за да помогне на вярващите да направят точно това.',
      'bn':
          'আমাদের লক্ষ্য হল বিশ্বাসীদেরকে তাদের বিশ্বে মহান কমিশন পূরণ করার জন্য প্রয়োজনীয় সরঞ্জামগুলির সাথে সজ্জিত করা এবং সজ্জিত করা। সুসমাচারের সাথে সবার কাছে পৌঁছাতে আমাদের সকলকে লাগে, এবং বিশ্বাসীদের ঠিক এটি করতে সহায়তা করার জন্য iEvangelize বিদ্যমান।',
      'bs':
          'Naša misija je da mobiliziramo i opremimo vjernike potrebnim alatima za ispunjavanje Velikog naloga u svom svijetu. Svima nam je potrebno da dopremo do svakoga sa Evanđeljem, a iEvangelize postoji da pomogne vjernicima da učine upravo to.',
      'ca':
          'La nostra missió és mobilitzar i equipar els creients amb les eines necessàries per complir la Gran Comissió al seu món. Cal que tots ens arribi a tothom amb l\'Evangeli, i iEvangelize existeix per ajudar els creients a fer-ho.',
      'cs':
          'Naším posláním je mobilizovat a vybavit věřící nezbytnými nástroji k naplnění Velkého poslání v jejich světě. Abychom oslovili každého evangeliem, potřebuje nás všechny a iEvangelize existuje, aby pomohla věřícím právě to udělat.',
      'da':
          'Vores mission er at mobilisere og udstyre troende med de nødvendige værktøjer til at opfylde Den Store Kommission i deres verden. Det kræver os alle at nå ud til alle med evangeliet, og iEvangelize eksisterer for at hjælpe troende med at gøre netop det.',
      'de':
          'Unsere Mission ist es, Gläubige zu mobilisieren und mit den notwendigen Werkzeugen auszustatten, um den Missionsbefehl in ihrer Welt zu erfüllen. Wir alle müssen alle mit dem Evangelium erreichen, und iEvangelize existiert, um Gläubigen dabei zu helfen.',
      'el':
          'Η αποστολή μας είναι να κινητοποιήσουμε και να εξοπλίσουμε τους πιστούς με τα απαραίτητα εργαλεία για να εκπληρώσουν τη Μεγάλη Επιστολή στον κόσμο τους. Χρειάζεται όλοι μας να προσεγγίσουμε όλους με το Ευαγγέλιο, και το iEvangelize υπάρχει για να βοηθήσει τους πιστούς να κάνουν ακριβώς αυτό.',
      'es':
          'Nuestra misión es movilizar y equipar a los creyentes con las herramientas necesarias para cumplir La Gran Comisión en su mundo. Se necesita de todos nosotros para llegar a todos con el Evangelio, y iEvangelize existe para ayudar a los creyentes a hacer precisamente eso.',
      'et':
          'Meie missiooniks on mobiliseerida ja varustada usklikke vajalike tööriistadega, et täita Suurt Komisjoni nende maailmas. Evangeeliumiga kõigini jõudmiseks on vaja meid kõiki ja iEvangelize on olemas selleks, et aidata usklikel just seda teha.',
      'eu':
          'Gure eginkizuna fededunei beren munduan The Great Commission betetzeko beharrezko tresnak mobilizatzea eta hornitzea da. Ebanjelioarekin guztiongana iristeko behar gaitu guztiok, eta iEvangelize existitzen da fededunei hori egiten laguntzeko.',
      'fa':
          'مأموریت ما بسیج و تجهیز مؤمنان به ابزارهای لازم برای انجام مأموریت بزرگ در دنیای خود است. همه ما لازم است تا با انجیل به همه دسترسی پیدا کنیم، و iEvangelize وجود دارد تا به ایمانداران کمک کند تا این کار را انجام دهند.',
      'fi':
          'Missiomme on mobilisoida ja varustaa uskovia tarvittavilla työkaluilla Suuren tehtävän täyttämiseksi heidän maailmassaan. Tarvitsemme meidät kaikki tavoittaaksemme kaikki evankeliumilla, ja iEvangelize on olemassa auttamaan uskovia tekemään juuri sen.',
      'fr':
          'Notre mission est de mobiliser et d\'équiper les croyants des outils nécessaires pour accomplir la Grande Commission dans leur monde. Il nous faut tous pour atteindre tout le monde avec l\'Évangile, et iEvangelize existe pour aider les croyants à faire exactement cela.',
      'gl':
          'A nosa misión é mobilizar e equipar aos crentes coas ferramentas necesarias para cumprir a Gran Comisión no seu mundo. Necesitamos todos chegar a todos co Evanxeo, e iEvangelize existe para axudar aos crentes a facelo.',
      'gu':
          'અમારું મિશન વિશ્વાસીઓને તેમના વિશ્વમાં ધ ગ્રેટ કમિશનને પરિપૂર્ણ કરવા માટે જરૂરી સાધનો સાથે એકત્રિત અને સજ્જ કરવાનું છે. ગોસ્પેલ સાથે દરેક સુધી પહોંચવામાં આપણા બધાને લાગે છે, અને આસ્થાવાનોને તે કરવામાં મદદ કરવા માટે iEvangelize અસ્તિત્વમાં છે.',
      'hi':
          'हमारा मिशन विश्वासियों को उनके संसार में महान आदेश को पूरा करने के लिए आवश्यक उपकरणों से लैस करना और संगठित करना है। सुसमाचार को सभी तक पहुँचाने के लिए हम सभी की ज़रूरत होती है, और iEvangelize विश्वासियों को ऐसा करने में मदद करने के लिए मौजूद है।',
      'hr':
          'Naša misija je mobilizirati i opremiti vjernike potrebnim alatima za ispunjenje Velikog poslanja u njihovom svijetu. Potrebno je da svi dopremo evanđelje do svih, a iEvangelize postoji kako bi pomogao vjernicima da učine upravo to.',
      'hu':
          'Küldetésünk, hogy mozgósítsuk és felszereljük a hívőket a szükséges eszközökkel ahhoz, hogy világukban teljesítsék a Nagy megbízatást. Mindannyiunkra szükség van ahhoz, hogy mindenkit elérjünk az evangéliummal, és az iEvangelize azért létezik, hogy segítse a hívőket ebben.',
      'hy':
          'Մեր առաքելությունն է մոբիլիզացնել և զինել հավատացյալներին անհրաժեշտ գործիքներով՝ իրենց աշխարհում Մեծ հանձնարարությունը կատարելու համար: Մեզնից բոլորից պահանջվում է Ավետարանով բոլորին հասնելու համար, և iEvangelize-ը գոյություն ունի, որպեսզի օգնի հավատացյալներին հենց դա անել:',
      'id':
          'Misi kami adalah untuk memobilisasi dan membekali umat beriman dengan alat yang diperlukan untuk memenuhi Amanat Agung di dunia mereka. Dibutuhkan kita semua untuk menjangkau semua orang dengan Injil, dan iEvangelize hadir untuk membantu orang-orang percaya melakukan hal itu.',
      'it':
          'La nostra missione è mobilitare e dotare i credenti degli strumenti necessari per adempiere al Grande Mandato nel loro mondo. Dobbiamo tutti raggiungere tutti con il Vangelo, e iEvangelize esiste per aiutare i credenti a fare proprio questo.',
      'ja':
          '私たちの使命は、信者を動員し、彼らの世界で大宣教命令を遂行するために必要なツールを提供することです。福音をすべての人に伝えるには私たち全員の力が必要です。iEvangelize は、まさに信者がそれを行えるように支援するために存在します。',
      'ka':
          'ჩვენი მისიაა მორწმუნეების მობილიზება და აღჭურვა საჭირო ინსტრუმენტებით, რათა შეასრულონ დიდი დავალება მათ სამყაროში. ყველა ჩვენგანს სჭირდება, რომ მივაწვდინოთ ყველას სახარება, და iEvangelize არსებობს, რათა დაეხმაროს მორწმუნეებს ამის გაკეთებაში.',
      'kn':
          'ಅವರ ಜಗತ್ತಿನಲ್ಲಿ ಗ್ರೇಟ್ ಕಮಿಷನ್ ಅನ್ನು ಪೂರೈಸಲು ಅಗತ್ಯವಾದ ಸಾಧನಗಳೊಂದಿಗೆ ಭಕ್ತರನ್ನು ಸಜ್ಜುಗೊಳಿಸುವುದು ಮತ್ತು ಸಜ್ಜುಗೊಳಿಸುವುದು ನಮ್ಮ ಉದ್ದೇಶವಾಗಿದೆ. ಸುವಾರ್ತೆಯೊಂದಿಗೆ ಪ್ರತಿಯೊಬ್ಬರನ್ನು ತಲುಪಲು ನಮ್ಮೆಲ್ಲರನ್ನೂ ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ ಮತ್ತು ನಂಬುವವರಿಗೆ ಅದನ್ನು ಮಾಡಲು ಸಹಾಯ ಮಾಡಲು iEvangelize ಅಸ್ತಿತ್ವದಲ್ಲಿದೆ.',
      'ko':
          '우리의 사명은 신자들이 세상에서 지상 명령을 이행하는 데 필요한 도구를 동원하고 준비시키는 것입니다. 모든 사람에게 복음을 전하려면 우리 모두가 필요하며, iEvangelize는 신자들이 그렇게 할 수 있도록 돕기 위해 존재합니다.',
      'lt':
          'Mūsų misija yra sutelkti ir aprūpinti tikinčiuosius reikiamais įrankiais, kad jie galėtų įvykdyti Didįjį pavedimą savo pasaulyje. Mums visiems reikia, kad Evangelija pasiektume kiekvieną, o iEvangelize egzistuoja tam, kad padėtų tikintiesiems tai padaryti.',
      'lv':
          'Mūsu misija ir mobilizēt un nodrošināt ticīgos ar nepieciešamajiem instrumentiem, lai izpildītu Lielo uzdevumu savā pasaulē. Mums visiem ir vajadzīgs, lai ar evaņģēliju sasniegtu ikvienu, un iEvangelize pastāv, lai palīdzētu ticīgajiem to darīt.',
      'mk':
          'Нашата мисија е да ги мобилизираме и опремиме верниците со потребните алатки за исполнување на Големата задача во нивниот свет. Потребни ни се сите нас да допреме до сите со Евангелието, а iEvangelize постои за да им помогне на верниците да го направат токму тоа.',
      'ml':
          'അവരുടെ ലോകത്ത് മഹത്തായ കമ്മീഷൻ നിറവേറ്റുന്നതിന് ആവശ്യമായ ഉപകരണങ്ങൾ വിശ്വാസികളെ അണിനിരത്തുകയും സജ്ജരാക്കുകയും ചെയ്യുക എന്നതാണ് ഞങ്ങളുടെ ദൗത്യം. സുവിശേഷവുമായി എല്ലാവരിലേക്കും എത്തിച്ചേരാൻ നമ്മളെല്ലാവരും ആവശ്യമാണ്, അത് ചെയ്യാൻ വിശ്വാസികളെ സഹായിക്കുന്നതിന് iEvangelize നിലവിലുണ്ട്.',
      'mn':
          'Бидний эрхэм зорилго бол итгэгчдийг өөрсдийн ертөнцөд Их Даалгаврыг биелүүлэхийн тулд шаардлагатай хэрэгслээр дайчлах, хангах явдал юм. Сайн мэдээг хүн бүрт хүргэхийн тулд бид бүгдээс хэрэгтэй бөгөөд iEvangelize нь итгэгчдэд үүнийг хийхэд нь туслах зорилготой юм.',
      'mr':
          'आमचे ध्येय विश्वासूंना त्यांच्या जगात द ग्रेट कमिशन पूर्ण करण्यासाठी आवश्यक साधनांसह एकत्रित करणे आणि सुसज्ज करणे हे आहे. गॉस्पेल प्रत्येकापर्यंत पोहोचण्यासाठी आपल्या सर्वांना आवश्यक आहे, आणि विश्वासणाऱ्यांना ते करण्यास मदत करण्यासाठी iEvangelize अस्तित्वात आहे.',
      'ms':
          'Misi kami adalah untuk menggerakkan dan melengkapkan orang beriman dengan alat yang diperlukan untuk memenuhi Amanah Agung di dunia mereka. Kita semua memerlukan kita untuk menjangkau semua orang dengan Injil, dan iEvangelize wujud untuk membantu orang percaya melakukan perkara itu.',
      'my':
          'ကျွန်ုပ်တို့၏တာဝန်မှာ ၎င်းတို့၏ကမ္ဘာရှိ မဟာကော်မရှင်ကို ဖြည့်ဆည်းရန် လိုအပ်သောကိရိယာများဖြင့် ယုံကြည်သူများကို စုစည်းပြီး တပ်ဆင်ပေးရန်ဖြစ်သည်။ ဧဝံဂေလိတရားနှင့်အတူလူတိုင်းထံရောက်ရှိရန်ကျွန်ုပ်တို့အားလုံးလိုအပ်ပြီးယုံကြည်သူများကိုကူညီရန် iEvangelize ရှိသည်။',
      'ne':
          'हाम्रो मिशन भनेको विश्वासीहरूलाई तिनीहरूको संसारमा महान् आयोग पूरा गर्न आवश्यक उपकरणहरूसँग परिचालन र सुसज्जित गर्नु हो। सबैलाई सुसमाचारको साथमा पुग्न हामी सबैलाई लाग्छ, र विश्वासीहरूलाई त्यसो गर्न मद्दत गर्नको लागि iEvangelize अवस्थित छ।',
      'nl':
          'Onze missie is om gelovigen te mobiliseren en uit te rusten met de noodzakelijke hulpmiddelen om De Grote Opdracht in hun wereld te vervullen. We hebben ons allemaal nodig om iedereen met het Evangelie te bereiken, en iEvangelize is er om gelovigen te helpen precies dat te doen.',
      'no':
          'Vårt oppdrag er å mobilisere og utstyre troende med de nødvendige verktøyene for å oppfylle Den Store Kommisjonen i deres verden. Det tar oss alle å nå alle med evangeliet, og iEvangelize eksisterer for å hjelpe troende til å gjøre nettopp det.',
      'or':
          'ଆମର ଲକ୍ଷ୍ୟ ହେଉଛି ବିଶ୍ believers ାସୀଙ୍କୁ ସେମାନଙ୍କ ଦୁନିଆରେ ମହାନ ଆୟୋଗ ପୂରଣ କରିବା ପାଇଁ ଆବଶ୍ୟକ ଉପକରଣ ସହିତ ସଜାଇବା | ସୁସମାଚାର ସହିତ ସମସ୍ତଙ୍କ ନିକଟରେ ପହଞ୍ଚିବା ପାଇଁ ଆମ ସମସ୍ତଙ୍କୁ ଲାଗେ, ଏବଂ ବିଶ୍ believers ାସୀଙ୍କୁ ତାହା କରିବାରେ ସାହାଯ୍ୟ କରିବାକୁ iEvangelize ବିଦ୍ୟମାନ |',
      'pa':
          'ਸਾਡਾ ਮਿਸ਼ਨ ਵਿਸ਼ਵਾਸੀਆਂ ਨੂੰ ਉਹਨਾਂ ਦੇ ਸੰਸਾਰ ਵਿੱਚ ਮਹਾਨ ਕਮਿਸ਼ਨ ਨੂੰ ਪੂਰਾ ਕਰਨ ਲਈ ਲੋੜੀਂਦੇ ਸਾਧਨਾਂ ਨਾਲ ਲਾਮਬੰਦ ਕਰਨਾ ਅਤੇ ਲੈਸ ਕਰਨਾ ਹੈ। ਇੰਜੀਲ ਨਾਲ ਹਰ ਕਿਸੇ ਤੱਕ ਪਹੁੰਚਣ ਲਈ ਸਾਨੂੰ ਸਾਰਿਆਂ ਨੂੰ ਲੱਗਦਾ ਹੈ, ਅਤੇ ਵਿਸ਼ਵਾਸੀਆਂ ਨੂੰ ਅਜਿਹਾ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਨ ਲਈ iEvangelize ਮੌਜੂਦ ਹੈ।',
      'pl':
          'Naszą misją jest mobilizacja i wyposażenie wierzących w narzędzia niezbędne do wypełnienia Wielkiego Nakazu Misyjnego w ich świecie. Dotarcie z Ewangelią do każdego wymaga każdego z nas, a iEvangelize istnieje po to, aby pomóc wierzącym w tym.',
      'pt':
          'A nossa missão é mobilizar e equipar os crentes com as ferramentas necessárias para cumprir a Grande Comissão no seu mundo. São necessários todos nós para alcançar a todos com o Evangelho, e o iEvangelize existe para ajudar os crentes a fazer exatamente isso.',
      'ro':
          'Misiunea noastră este să mobilizăm și să echipăm credincioșii cu instrumentele necesare pentru a îndeplini Marea Trimitere în lumea lor. Este nevoie de toți pentru a ajunge la toată lumea cu Evanghelia, iar iEvangelize există pentru a ajuta credincioșii să facă exact asta.',
      'ru':
          'Наша миссия — мобилизовать и снабдить верующих необходимыми инструментами для выполнения Великого Поручения в их мире. Нам всем нужно донести Евангелие до каждого, и iEvangelize существует для того, чтобы помочь верующим сделать именно это.',
      'sd':
          'اسان جو مشن مومنن کي متحرڪ ۽ ليس ڪرڻ آهي ضروري اوزارن سان گڏ انهن جي دنيا ۾ عظيم ڪميشن کي پورو ڪرڻ لاءِ. اهو اسان سڀني کي وٺي ٿو هر ڪنهن تائين انجيل تائين پهچڻ لاءِ، ۽ iEvangelize موجود آهي ايمان وارن کي اهو ڪرڻ ۾ مدد ڏيڻ لاءِ.',
      'si':
          'අපගේ මෙහෙවර වන්නේ ඇදහිලිවන්තයන් ඔවුන්ගේ ලෝකයේ මහා කොමිසම ඉටු කිරීමට අවශ්‍ය මෙවලම් බලමුලු ගැන්වීම සහ සන්නද්ධ කිරීමයි. ශුභාරංචිය සමඟ සෑම කෙනෙකුටම ළඟා වීමට අප සැමට අවශ්‍ය වන අතර, ඇදහිලිවන්තයන්ට එය කිරීමට උපකාර කිරීමට iEvangelize පවතී.',
      'sk':
          'Naším poslaním je mobilizovať a vybaviť veriacich potrebnými nástrojmi na naplnenie Veľkého poverenia v ich svete. Je potrebné, aby sme všetci oslovili evanjeliom a iEvangelize existuje, aby pomohla veriacim urobiť práve to.',
      'sl':
          'Naše poslanstvo je mobilizirati in opremiti vernike s potrebnimi orodji za izpolnjevanje Velike naloge v njihovem svetu. Vsi moramo doseči vsakogar z evangelijem in iEvangelize obstaja, da pomaga vernikom storiti prav to.',
      'sq':
          'Misioni ynë është të mobilizojmë dhe pajisim besimtarët me mjetet e nevojshme për të përmbushur Urdhrin e Madh në botën e tyre. Na duhet të gjithëve që t\'i arrijmë të gjithëve me Ungjillin dhe iEvangelize ekziston për të ndihmuar besimtarët të bëjnë pikërisht këtë.',
      'sr':
          'Наша мисија је да мобилишемо и опремимо вернике неопходним алатима за испуњавање Великог налога у свом свету. Свима нам је потребно да допремо до свакога са Јеванђељем, а иЕвангелизе постоји да би помогао верницима да учине управо то.',
      'sv':
          'Vårt uppdrag är att mobilisera och utrusta troende med de nödvändiga verktygen för att uppfylla The Great Commission i deras värld. Det krävs för oss alla att nå alla med evangeliet, och iEvangelize finns till för att hjälpa troende att göra just det.',
      'ta':
          'எங்கள் நோக்கம் விசுவாசிகளை அவர்களின் உலகில் தி கிரேட் கமிஷனை நிறைவேற்ற தேவையான கருவிகளை அணிதிரட்டி சித்தப்படுத்துவதாகும். நற்செய்தியுடன் அனைவரையும் சென்றடைய நாம் அனைவரும் தேவைப்படுகிறோம், விசுவாசிகள் அதைச் செய்ய iEvangelize உள்ளது.',
      'tr':
          'Misyonumuz, inananları kendi dünyalarında Büyük Görevi yerine getirmek için gerekli araçlarla harekete geçirmek ve donatmaktır. Müjdeyi herkese ulaştırmak hepimizi gerektirir ve iEvangelize, inananların tam da bunu yapmasına yardımcı olmak için vardır.',
      'uk':
          'Наша місія полягає в тому, щоб мобілізувати віруючих і оснастити їх необхідними інструментами для виконання Великого Доручення в їхньому світі. Усім нам потрібно, щоб донести Євангеліє до кожного, і iEvangelize існує, щоб допомогти віруючим зробити саме це.',
      'ur':
          'ہمارا مشن مومنین کو ان کی دنیا میں عظیم کمیشن کو پورا کرنے کے لیے ضروری آلات کے ساتھ متحرک اور لیس کرنا ہے۔ انجیل کے ساتھ ہر ایک تک پہنچنے میں ہم سب کو لگتا ہے، اور ایمانداروں کو ایسا کرنے میں مدد کرنے کے لیے iEvangelize موجود ہے۔',
      'uz':
          'Bizning vazifamiz imonlilarni o\'z dunyolarida Buyuk topshiriqni bajarish uchun zarur vositalar bilan safarbar qilish va jihozlashdir. Xushxabarni hammaga yetkazish uchun barchamiz kerak bo\'ladi va iEvangelize imonlilarga buni qilishga yordam berish uchun mavjud.',
      'vi':
          'Sứ mệnh của chúng tôi là huy động và trang bị cho các tín đồ những công cụ cần thiết để hoàn thành Đại Mạng Lệnh trong thế giới của họ. Tất cả chúng ta cần phải tiếp cận mọi người bằng Phúc âm, và iEvangelize tồn tại để giúp các tín đồ làm điều đó.',
      'zh_Hans':
          '我们的使命是动员信徒并为他们提供必要的工具，以在他们所在的世界中实现大使命。我们所有人都需要努力才能将福音传给每个人，而 iEvangelize 的存在就是为了帮助信徒做到这一点。',
      'zh_Hant':
          '我們的使命是動員信徒並為其配備必要的工具，以在他們的世界中實現大使命。我們所有人都需要將福音傳給每個人，而 iEvangelize 的存在就是為了幫助信徒做到這一點。',
    },
