  {
    '204wmd8a': {
      'en': 'Who do you want to\nevangelize to?',
      'am': 'ማንን ይፈልጋሉ\nወንጌልን ለመስበክ?',
      'ar': 'من تريد\nتبشير ل؟',
      'be': 'Каму хочаш\nевангелізаваць?',
      'bg': 'Кой искате да\nевангелизирам към?',
      'bn': 'আপনি কে চান\nসুসমাচার প্রচার করা?',
      'bs': 'Koga želiš\nevangelizovati to?',
      'ca': 'A qui vols\nevangelitzar a?',
      'cs': 'kdo chcete\nevangelizovat?',
      'da': 'Hvem vil du\nevangelisere til?',
      'de': 'Wen möchten Sie\nevangelisieren?',
      'el': 'Ποιον θέλεις\nευαγγελίζω σε;',
      'es': '¿A quién quieres?\nevangelizar a?',
      'et': 'Keda sa tahad\nevangeliseerida?',
      'eu': 'Nor nahi duzu\nebanjelizatzeko?',
      'fa': 'چه کسی را می خواهید\nبشارت دادن به؟',
      'fi': 'Kenet haluat\njulistaa evankeliumia jklle?',
      'fr': 'À qui veux-tu\névangéliser ?',
      'gl': 'A quen queres\nevanxelizar a?',
      'gu': 'તમે કોને કરવા માંગો છો\nમાટે પ્રચાર?',
      'hi': 'आप किसे सुसमाचार सुनाना चाहते हैं?',
      'hr': 'Koga želite\nevangelizirati?',
      'hu': 'kit akarsz\nevangelizálni?',
      'hy': 'ում եք ուզում\nավետարանել?',
      'id': 'Siapa yang kamu inginkan\nmenginjili?',
      'it': 'Chi vuoi?\nevangelizzare?',
      'ja': '誰に伝道したいですか？',
      'ka': 'ვის გინდათ\nევანგელიზაცია?',
      'kn': 'ನೀವು ಯಾರನ್ನು ಬಯಸುತ್ತೀರಿ\nಸುವಾರ್ತೆ ಸಾರುವುದೇ?',
      'ko': '누구를 원하시나요?\n복음을 전하다?',
      'lt': 'Kas nori\nevangelizuoti?',
      'lv': 'Kuru tu gribi\nevaņģelizēt?',
