    'rn85iic1': {
      'en':
          'By \"convert,\" we are referring to someone who said Yes to Jesus, i.e., they accepted Jesus as thier Lord and Savior. \n\nBy \"seed,\" we are referring to someone with whom you shared your faith but didn\'t give their life to Jesus. But it is not a loss, as the bible tells us that some plant and some water, but God brings the increase (1 Cor 3:6-7).\n',
      'am':
          '“መለወጥ” ስንል ኢየሱስን አዎ ያለውን ሰው ማለትም ኢየሱስን እንደ ጌታ እና አዳኝ አድርገው የተቀበሉትን ማለታችን ነው።\n\nበ\"ዘር\" እምነትህን የተካፈልከውን ነገር ግን ህይወቱን ለኢየሱስ ያልሰጠህ ሰውን እንጠቅሳለን። ነገር ግን አንዳንድ ተክሎች አንዳንድ ውኃዎች ግን እግዚአብሔር እንደሚያድግ መጽሐፍ ቅዱስ እንደሚነግረን ኪሳራ አይደለም (1ኛ ቆሮ 3፡6-7)።',
      'ar':
          'بكلمة \"تحول\" نشير إلى شخص قال \"نعم\" ليسوع، أي أنهم قبلوا يسوع ربًا ومخلصًا لهم.\n\nبكلمة \"نسل\" نشير إلى شخص شاركت معه إيمانك ولكنك لم تهب حياته ليسوع. ولكنها ليست خسارة، إذ يخبرنا الكتاب أن بعض النبات وبعض الماء ولكن الله يأتي بالنمو (1كو3: 6-7).',
      'be':
          'Пад «навяртаннем» мы маем на ўвазе таго, хто сказаў Езусу «так», гэта значыць, што ён прыняў Езуса як свайго Пана і Збаўцу.\n\nПад «насеннем» мы маем на ўвазе таго, з кім вы падзялялі сваю веру, але не аддалі сваё жыццё Езусу. Але гэта не страта, бо Біблія кажа нам, што некаторыя расліны і некаторыя паліваюць, але Бог прыносіць рост (1 Кар 3: 6-7).',
      'bg':
          'Под „обръщане“ имаме предвид някой, който е казал „Да“ на Исус, т.е. те са приели Исус за свой Господ и Спасител.\n\nПод „семе“ имаме предвид някой, с когото сте споделили вярата си, но не сте дали живота си на Исус. Но това не е загуба, тъй като Библията ни казва, че някои растения и малко вода, но Бог носи растежа (1 Коринтяни 3:6-7).',
      'bn':
          '\"রূপান্তর\" দ্বারা আমরা এমন একজনকে উল্লেখ করছি যিনি যীশুকে হ্যাঁ বলেছিলেন, অর্থাৎ, তারা যীশুকে তার প্রভু এবং ত্রাণকর্তা হিসাবে গ্রহণ করেছিলেন।\n\n\"বীজ\" দ্বারা আমরা এমন একজনকে উল্লেখ করছি যার সাথে আপনি আপনার বিশ্বাস ভাগ করেছেন কিন্তু যীশুকে তাদের জীবন দেননি। কিন্তু এটি ক্ষতি নয়, যেমন বাইবেল আমাদের বলে যে কিছু গাছপালা এবং কিছু জল, কিন্তু ঈশ্বর বৃদ্ধি আনেন (1 Cor 3:6-7)।',
      'bs':
          'Pod \"preobratiti\" mislimo na nekoga ko je rekao Da Isusu, tj. prihvatili su Isusa kao svog Gospoda i Spasitelja.\n\nPod \"semenom\" mislimo na nekoga s kim ste dijelili svoju vjeru, ali niste dali svoj život Isusu. Ali to nije gubitak, kao što nam Biblija kaže da su neke biljke, a nešto voda, ali Bog donosi povećanje (1 Kor 3,6-7).',
      'ca':
          'Per \"convertir\", ens referim a algú que va dir Sí a Jesús, és a dir, va acceptar Jesús com el seu Senyor i Salvador.\n\nPer \"llavor\", ens referim a algú amb qui vas compartir la teva fe però no vas donar la vida a Jesús. Però no és una pèrdua, ja que la Bíblia ens diu que algunes plantes i una mica d\'aigua, però Déu en porta l\'augment (1 Co 3,6-7).',
      'cs':
          '„Obrácením“ máme na mysli někoho, kdo řekl Ježíši ano, tj. přijal Ježíše jako svého Pána a Spasitele.\n\n„Semeno“ máme na mysli někoho, s kým jste sdíleli svou víru, ale nedali svůj život Ježíši. Ale není to ztráta, jak nám Bible říká, že některé rostliny a trochu vody, ale Bůh přináší růst (1 Kor 3:6-7).',
      'da':
          'Med \"omvendelse\" refererer vi til nogen, der sagde ja til Jesus, dvs. de accepterede Jesus som deres Herre og Frelser.\n\nMed \"afkom\" refererer vi til nogen, som du delte din tro med, men som ikke gav deres liv til Jesus. Men det er ikke et tab, da Bibelen fortæller os, at nogle planter og noget vand, men Gud bringer stigningen (1 Kor 3,6-7).',
      'de':
          'Mit „Konvertit“ meinen wir jemanden, der „Ja“ zu Jesus gesagt hat, d. h., er hat Jesus als seinen Herrn und Erlöser angenommen. \n\nMit „Same“ meinen wir jemanden, mit dem Sie Ihren Glauben geteilt haben, der sein Leben aber nicht Jesus gewidmet hat. Aber es ist kein Verlust, denn die Bibel sagt uns, dass manche pflanzen und manche gießen, aber Gott das Wachstum bringt (1 Kor 3,6-7).',
      'el':
          'Με τον όρο «μεταστράτευση», αναφερόμαστε σε κάποιον που είπε Ναι στον Ιησού, δηλ. δέχτηκε τον Ιησού ως Κύριο και Σωτήρα τους.\n\nΜε τον όρο \"σπόρος\", αναφερόμαστε σε κάποιον με τον οποίο μοιραστήκατε την πίστη σας αλλά δεν δώσατε τη ζωή του στον Ιησού. Αλλά δεν είναι απώλεια, όπως μας λέει η Αγία Γραφή ότι μερικά φυτά και λίγο νερό, αλλά ο Θεός φέρνει την αύξηση (Α Κορ. 3:6-7).',
      'es':
          'Por \"convertir\", nos referimos a alguien que dijo Sí a Jesús, es decir, aceptó a Jesús como su Señor y Salvador.\n\nPor \"semilla\" nos referimos a alguien con quien compartiste tu fe pero no le dio su vida a Jesús. Pero no es pérdida, como nos dice la biblia que algunas plantas y un poco riegan, pero Dios trae el crecimiento (1 Cor 3:6-7).',
      'et':
          'Sõnaga \"pöördumine\" peame silmas kedagi, kes ütles Jeesusele jah, st nad võtsid Jeesuse vastu oma Issanda ja Päästjana.\n\n\"Seeme\" all peame silmas kedagi, kellega jagasite oma usku, kuid ei andnud oma elu Jeesusele. Kuid see ei ole kaotus, nagu piibel ütleb, et mõned taimed ja mõned vesi, kuid Jumal toob kasvu (1Kr 3:6-7).',
      'eu':
          '\"Bihurtu\" esanez, Jesusi baietz esan zion norbaiti ari gara, hau da, Jesus bere Jaun eta Salbatzaile gisa onartu zuten.\n\n\"Hazia\" erabiliz, zure fedea partekatu baina Jesusi bizia eman ez diozun norbaiti ari gara. Baina ez da galera, Bibliak esaten digunez landare batzuk eta ur batzuk, baina Jainkoak gehikuntza ekartzen du (1 Ko 3:6-7).',
      'fa':
          'منظور ما از \"تبدیل\" کسی است که به عیسی بله گفت، یعنی عیسی را به عنوان خداوند و نجات دهنده خود پذیرفتند.\n\nمنظور ما از \"بذر\" شخصی است که شما با او در ایمان خود شریک بودید اما جان خود را به عیسی ندادید. اما این یک ضرر نیست، همانطور که کتاب مقدس به ما می گوید که برخی از گیاهان و برخی آب، اما خدا افزایش می دهد (اول قرنتیان 3: 6-7).',
      'fi':
          'Sanalla \"käännynnäinen\" tarkoitamme jotakuta, joka sanoi Jeesukselle kyllä, ts. hän hyväksyi Jeesuksen Herrakseen ja Vapahtajakseen.\n\n\"Siemenellä\" tarkoitamme henkilöä, jonka kanssa jaoit uskosi, mutta et antanut elämäänsä Jeesukselle. Mutta se ei ole menetys, kuten Raamattu kertoo, että jotkut kasvit ja toiset vettä, mutta Jumala tuo lisäyksen (1. Kor. 3:6-7).',
      'fr':
          'Par « convertir », nous faisons référence à quelqu\'un qui a dit oui à Jésus, c\'est-à-dire qu\'il a accepté Jésus comme son Seigneur et Sauveur.\n\nPar « postérité », nous faisons référence à quelqu\'un avec qui vous avez partagé votre foi mais qui n\'a pas donné sa vie à Jésus. Mais ce n\'est pas une perte, comme la Bible nous le dit, quelques plantes et un peu d\'eau, mais Dieu apporte l\'augmentation (1 Cor 3 :6-7).',
      'gl':
          'Por \"converter\", referímonos a alguén que lle dixo si a Xesús, é dicir, aceptaba a Xesús como o seu Señor e Salvador.\n\nPor \"semente\" referímonos a alguén con quen compartiu a súa fe pero non lle deu a vida a Xesús. Pero non é unha perda, xa que a Biblia nos di que algunhas plantas e algo de auga, pero Deus trae o aumento (1 Co 3, 6-7).',
      'gu':
          '\"રૂપાંતર\" દ્વારા આપણે એવા વ્યક્તિનો ઉલ્લેખ કરી રહ્યા છીએ જેણે ઈસુને હા કહ્યું, એટલે કે, તેઓએ ઈસુને તેના ભગવાન અને તારણહાર તરીકે સ્વીકાર્યા.\n\n\"બીજ\" દ્વારા, અમે એવી વ્યક્તિનો ઉલ્લેખ કરી રહ્યા છીએ કે જેની સાથે તમે તમારો વિશ્વાસ શેર કર્યો છે પરંતુ તેણે ઈસુને પોતાનો જીવ આપ્યો નથી. પરંતુ તે નુકસાન નથી, કારણ કે બાઇબલ આપણને કહે છે કે કેટલાક છોડ અને કેટલાક પાણી, પરંતુ ભગવાન વધારો લાવે છે (1 કોરીં 3: 6-7).',
      'hi':
          '\"परिवर्तन\" से हमारा तात्पर्य ऐसे व्यक्ति से है जिसने यीशु को हाँ कहा, यानी, उन्होंने यीशु को अपना प्रभु और उद्धारकर्ता स्वीकार किया।\n\n\"बीज\" से हमारा तात्पर्य ऐसे व्यक्ति से है जिसके साथ आपने अपना विश्वास साझा किया लेकिन यीशु को अपना जीवन नहीं दिया। लेकिन यह कोई नुकसान नहीं है, जैसा कि बाइबल हमें बताती है कि कुछ पौधे और कुछ पानी, लेकिन परमेश्वर वृद्धि लाता है (1 कुरिं 3:6-7)।',
      'hr':
          'Pod \"obraćenjem\" mislimo na nekoga tko je rekao Da Isusu, tj. prihvatio je Isusa kao svog Gospodina i Spasitelja.\n\nPod \"sjemenom\" mislimo na nekoga s kim ste dijelili svoju vjeru, ali niste predali svoj život Isusu. Ali to nije gubitak, kao što nam biblija kaže da neko sadi, a neko zalijeva, nego Bog donosi rast (1 Kor 3,6-7).',
      'hu':
          'A \"megtért\" alatt valakire utalunk, aki igent mondott Jézusnak, azaz elfogadta Jézust Urának és Megváltójának.\n\nA „mag” alatt valakire utalunk, akivel megosztottad a hitedet, de nem Jézusnak adtad az életét. De ez nem veszteség, hiszen a Biblia azt mondja, hogy egyes növények és víz, de Isten hozza a növekedést (1Kor 3:6-7).',
      'hy':
          '«Դարձի գալ» ասելով մենք նկատի ունենք մեկին, ով ասաց այո Հիսուսին, այսինքն՝ նրանք ընդունեցին Հիսուսին որպես իրենց Տեր և Փրկիչ:\n\n«Սերմ» ասելով մենք նկատի ունենք մեկին, ում հետ դուք կիսում էիք ձեր հավատքը, բայց նրանց կյանքը չտվեցիք Հիսուսին: Բայց դա կորուստ չէ, քանի որ Աստվածաշունչը մեզ ասում է, որ որոշ բույսեր և որոշ ջուր, բայց Աստված է աճեցնում (1 Կորնթ. 3:6-7):',
      'id':
          'Yang kami maksud dengan “bertobat” adalah seseorang yang mengatakan Ya kepada Yesus, yaitu mereka menerima Yesus sebagai Tuhan dan Juruselamatnya.\n\nYang kami maksud dengan \"benih\" adalah seseorang yang dengannya Anda berbagi iman tetapi tidak menyerahkan nyawanya kepada Yesus. Namun hal ini bukanlah sebuah kerugian, seperti yang dikatakan Alkitab kepada kita bahwa ada tanaman dan sedikit air, namun Tuhanlah yang memberi pertumbuhan (1Kor. 3:6-7).',
      'it':
          'Per \"convertirsi\" ci riferiamo a qualcuno che ha detto sì a Gesù, cioè ha accettato Gesù come suo Signore e Salvatore.\n\nPer \"seme\" ci riferiamo a qualcuno con cui hai condiviso la tua fede ma non hai dato la vita a Gesù. Ma non è una perdita, poiché la Bibbia ci dice che alcune piante e un po\' di acqua, ma Dio fa crescere (1 Cor 3:6-7).',
      'ja':
          '「改宗者」とは、イエスに「はい」と言った人、つまりイエスを主であり救い主として受け入れた人のことです。\n\n「種」とは、信仰を共有したがイエスに命を捧げなかった人のことです。しかし、聖書には、植物や水はあっても、神が成長をもたらすと書かれているように、それは損失ではありません（コリント人への第一の手紙 3:6-7）。',
      'ka':
          '„მოქცევით“ ჩვენ ვგულისხმობთ ვინმეს, ვინც თქვა დიახ იესოს, ანუ მათ მიიღეს იესო, როგორც თავიანთი უფალი და მხსნელი.\n\n„თესლში“ ჩვენ ვგულისხმობთ ვინმეს, ვისთანაც თქვენ იზიარებდით თქვენს რწმენას, მაგრამ არ უთმეთ სიცოცხლე იესოს. მაგრამ ეს არ არის დანაკარგი, როგორც ბიბლია გვეუბნება, რომ ზოგი მცენარე და ზოგი წყალი, მაგრამ ღმერთი მოაქვს ზრდას (1 კორ 3:6-7).',
      'kn':
          '\"ಮತಾಂತರ\" ಮಾಡುವ ಮೂಲಕ, ನಾವು ಯೇಸುವಿಗೆ ಹೌದು ಎಂದು ಹೇಳಿದ ವ್ಯಕ್ತಿಯನ್ನು ಉಲ್ಲೇಖಿಸುತ್ತಿದ್ದೇವೆ, ಅಂದರೆ, ಅವರು ಯೇಸುವನ್ನು ತಮ್ಮ ಲಾರ್ಡ್ ಮತ್ತು ರಕ್ಷಕ ಎಂದು ಒಪ್ಪಿಕೊಂಡರು.\n\n\"ಬೀಜ\" ದ ಮೂಲಕ, ನೀವು ಯಾರೊಂದಿಗೆ ನಿಮ್ಮ ನಂಬಿಕೆಯನ್ನು ಹಂಚಿಕೊಂಡಿದ್ದೀರಿ ಆದರೆ ಅವರ ಜೀವನವನ್ನು ಯೇಸುವಿಗೆ ನೀಡಲಿಲ್ಲ ಎಂದು ನಾವು ಉಲ್ಲೇಖಿಸುತ್ತಿದ್ದೇವೆ. ಆದರೆ ಇದು ನಷ್ಟವಲ್ಲ, ಕೆಲವು ಸಸ್ಯಗಳು ಮತ್ತು ಸ್ವಲ್ಪ ನೀರು ಎಂದು ಬೈಬಲ್ ಹೇಳುತ್ತದೆ, ಆದರೆ ದೇವರು ಹೆಚ್ಚಳವನ್ನು ತರುತ್ತಾನೆ (1 ಕೊರಿ 3:6-7).',
      'ko':
          '\"회심하다\"는 말은 예수께 \'예\'라고 대답한 사람, 즉 예수를 자신의 주님과 구세주로 영접한 사람을 의미합니다.\n\n“씨”는 여러분과 믿음을 나누었지만 그들의 삶을 예수님께 드리지 않은 사람을 의미합니다. 그러나 성경에서 말하는 것처럼 그것은 손실이 아닙니다. 식물과 물은 하나님께서 자라나게 하십니다(고전 3:6-7).',
      'lt':
          'Sakydami „atsivertimą“ turime omenyje žmogų, kuris pasakė Jėzui „Taip“, t. y. priėmė Jėzų kaip savo Viešpatį ir Gelbėtoją.\n\n„Sėkla“ reiškia žmogų, su kuriuo pasidalinote savo tikėjimu, bet neatidavei savo gyvenimo Jėzui. Bet tai nėra nuostolis, kaip Biblija mums sako, kad kai kurie augalai, o kai kurie vanduo, bet Dievas atneša prieaugį (1 Kor 3, 6-7).',
      'lv':
          'Ar \"pievērstību\" mēs domājam kādu, kurš teica Jēzum Jā, t.i., viņi pieņēma Jēzu kā savu Kungu un Glābēju.\n\nAr \"sēklu\" mēs domājam kādu, ar kuru jūs dalījāties savā ticībā, bet neatdevāt savu dzīvību Jēzum. Bet tas nav zaudējums, kā Bībele saka, ka daži augi un daži ūdens, bet Dievs nes pieaugumu (1. Kor 3:6-7).',
      'mk':
          'Под „преобратете се“, ние се мислиме на некој кој му рекол Да на Исус, т.е. го прифатиле Исус како свој Господ и Спасител.\n\nПод „семе“, ние мислиме на некој со кого сте ја споделиле вашата вера, но не му го дале животот на Исус. Но, тоа не е загуба, како што Библијата ни кажува дека некои растенија и малку вода, туку Бог го носи зголемувањето (1 Кор 3:6-7).',
      'ml':
          '\"പരിവർത്തനം\" എന്നതുകൊണ്ട്, യേശുവിനോട് അതെ എന്ന് പറഞ്ഞ ഒരാളെയാണ് ഞങ്ങൾ പരാമർശിക്കുന്നത്, അതായത്, അവർ യേശുവിനെ തങ്ങളുടെ കർത്താവും രക്ഷകനും ആയി അംഗീകരിച്ചു.\n\n\"സന്തതി\" എന്നതു കൊണ്ട്, നിങ്ങൾ നിങ്ങളുടെ വിശ്വാസം പങ്കുവെച്ചെങ്കിലും അവരുടെ ജീവിതം യേശുവിന് നൽകാത്ത ഒരാളെയാണ് ഞങ്ങൾ പരാമർശിക്കുന്നത്. എന്നാൽ അത് ഒരു നഷ്ടമല്ല, ചില ചെടികളും കുറച്ച് വെള്ളവും എന്ന് ബൈബിൾ നമ്മോട് പറയുന്നതുപോലെ, ദൈവം വർദ്ധിപ്പിക്കുന്നു (1 കോറി 3:6-7).',
      'mn':
          '\"Хөрвүүлэлт\" гэдэг нь бид Есүст Тийм гэж хэлсэн, өөрөөр хэлбэл тэд Есүсийг өөрийн Эзэн, Аврагч гэж хүлээн зөвшөөрсөн хүнийг хэлж байна.\n\n\"Үр\" гэдэг үгээр бид таны итгэлийг хуваалцаж байсан ч Есүст амиа өгөөгүй хэн нэгнийг хэлж байна. Гэхдээ энэ нь алдагдал биш, учир нь библид зарим ургамал, зарим ус, харин Бурхан өсөлтийг авчирдаг гэж хэлдэг (1 Кор 3:6-7).',
      'mr':
          '\"धर्मांतर\" करून, आम्ही अशा व्यक्तीचा संदर्भ देत आहोत ज्याने येशूला होय म्हटले, म्हणजेच त्यांनी येशूला आपला प्रभु आणि तारणहार म्हणून स्वीकारले.\n\n\"बीज\" द्वारे आम्ही अशा व्यक्तीचा संदर्भ देत आहोत ज्यांच्याशी तुम्ही तुमचा विश्वास सामायिक केला आहे परंतु येशूला त्यांचे जीवन दिले नाही. परंतु हे नुकसान नाही, जसे बायबल आपल्याला सांगते की काही वनस्पती आणि काही पाणी, परंतु देव वाढ आणतो (1 करिंथ 3:6-7).',
      'ms':
          'Dengan \"mualaf,\" kita merujuk kepada seseorang yang berkata Ya kepada Yesus, iaitu, mereka menerima Yesus sebagai Tuhan dan Penyelamat mereka.\n\nDengan \"benih\", kami merujuk kepada seseorang yang anda berkongsi kepercayaan anda tetapi tidak menyerahkan nyawanya kepada Yesus. Tetapi ia tidak rugi, kerana bible memberitahu kita bahawa beberapa tumbuhan dan beberapa air, tetapi Tuhan yang mendatangkan pertambahan (1 Kor 3:6-7).',
      'my':
          '\"ပြောင်းလဲခြင်း\" အားဖြင့် ကျွန်ုပ်တို့သည် ယေရှုအား Yes ဟုပြောသူတစ်ဦးကို ရည်ညွှန်းပြီး ဆိုလိုသည်မှာ၊ ယေရှုအား သူတို့၏သခင်နှင့် ကယ်တင်ရှင်အဖြစ် လက်ခံကြသည်။\n\n“အမျိုးအနွယ်” အားဖြင့် ကျွန်ုပ်တို့သည် သင်တို့၏ယုံကြည်ခြင်းကို မျှဝေပေးခဲ့ကြသော တစ်စုံတစ်ဦးကို ယေရှုအား ရည်ညွှန်းသော်လည်း သူတို့၏အသက်ကို သခင်ယေရှုအား မပေးအပ်ခဲ့ပေ။ အချို့သောအပင်များနှင့် ရေအချို့ကို သမ္မာကျမ်းစာက ဖော်ပြထားသကဲ့သို့ ဆုံးရှုံးမှုမဟုတ်သော်လည်း ဘုရားသခင်သည် တိုးပွားစေသည် (၁ကော ၃း၆-၇)။',
      'ne':
          '\"रूपान्तरण\" द्वारा हामीले येशूलाई हो भने, अर्थात्, तिनीहरूले येशूलाई आफ्नो प्रभु र मुक्तिदाताको रूपमा स्वीकार गर्ने व्यक्तिलाई संकेत गर्दैछौं।\n\n\"बीज\" द्वारा, हामीले त्यस्तो व्यक्तिलाई संकेत गर्दैछौं जससँग तपाईंले आफ्नो विश्वास साझा गर्नुभयो तर येशूलाई आफ्नो जीवन दिनुभएको छैन। तर यो नोक्सान होइन, जस्तो कि बाइबलले हामीलाई बताउँछ कि केही बोटबिरुवा र केही पानी, तर परमेश्वरले वृद्धि ल्याउनुहुन्छ (१ कोरिन्थी ३:६-७)।',
      'nl':
          'Met ‘bekeerling’ bedoelen we iemand die ‘ja’ zei tegen Jezus, dat wil zeggen: hij accepteerde Jezus als zijn Heer en Verlosser.\n\nMet ‘zaad’ bedoelen we iemand met wie u uw geloof deelde, maar zijn leven niet aan Jezus gaf. Maar het is geen verlies, zoals de bijbel ons vertelt dat sommige planten en wat water, maar God de toename brengt (1 Kor. 3:6-7).',
      'no':
          'Med «omvendt» sikter vi til noen som sa ja til Jesus, dvs. de tok imot Jesus som deres Herre og Frelser.\n\nMed «ætt» sikter vi til noen som du delte din tro med, men som ikke ga livet sitt til Jesus. Men det er ikke et tap, som Bibelen forteller oss at noen planter og litt vann, men Gud bringer økningen (1 Kor 3:6-7).',
      'or':
          '\"ରୂପାନ୍ତର\" ଦ୍ we ାରା, ଆମେ ଜଣଙ୍କୁ ସୂଚାଉଛୁ ଯିଏ ଯୀଶୁଙ୍କୁ ହଁ କହିଥଲେ, ଅର୍ଥାତ୍ ସେମାନେ ଯୀଶୁଙ୍କୁ ତୁମର ପ୍ରଭୁ ଏବଂ ତ୍ରାଣକର୍ତ୍ତା ଭାବରେ ଗ୍ରହଣ କଲେ |\n\n\"ମଞ୍ଜି\" ଦ୍ we ାରା, ଆମେ ସେହି ବ୍ୟକ୍ତିଙ୍କୁ ସୂଚାଉଛୁ ଯାହାଙ୍କ ସହ ତୁମେ ତୁମର ବିଶ୍ shared ାସ ବାଣ୍ଟିଛ କିନ୍ତୁ ଯୀଶୁଙ୍କୁ ସେମାନଙ୍କ ଜୀବନ ଦେଇ ନାହଁ | କିନ୍ତୁ ଏହା ଏକ କ୍ଷତି ନୁହେଁ, ଯେହେତୁ ବାଇବଲ ଆମକୁ କହିଛି ଯେ କିଛି ଉଦ୍ଭିଦ ଏବଂ କିଛି ଜଳ, କିନ୍ତୁ ଭଗବାନ ବୃଦ୍ଧି ଆଣନ୍ତି (୧ କରିନ୍ :: -7-)) |',
      'pa':
          '\"ਕਨਵਰਟ\" ਦੁਆਰਾ ਅਸੀਂ ਕਿਸੇ ਅਜਿਹੇ ਵਿਅਕਤੀ ਦਾ ਹਵਾਲਾ ਦੇ ਰਹੇ ਹਾਂ ਜਿਸ ਨੇ ਯਿਸੂ ਨੂੰ ਹਾਂ ਕਿਹਾ, ਭਾਵ, ਉਨ੍ਹਾਂ ਨੇ ਯਿਸੂ ਨੂੰ ਆਪਣੇ ਪ੍ਰਭੂ ਅਤੇ ਮੁਕਤੀਦਾਤਾ ਵਜੋਂ ਸਵੀਕਾਰ ਕੀਤਾ।\n\n\"ਅੰਸ\" ਦੁਆਰਾ ਅਸੀਂ ਕਿਸੇ ਅਜਿਹੇ ਵਿਅਕਤੀ ਦਾ ਜ਼ਿਕਰ ਕਰ ਰਹੇ ਹਾਂ ਜਿਸ ਨਾਲ ਤੁਸੀਂ ਆਪਣੀ ਨਿਹਚਾ ਸਾਂਝੀ ਕੀਤੀ ਸੀ ਪਰ ਯਿਸੂ ਨੂੰ ਆਪਣੀ ਜਾਨ ਨਹੀਂ ਦਿੱਤੀ। ਪਰ ਇਹ ਕੋਈ ਨੁਕਸਾਨ ਨਹੀਂ ਹੈ, ਜਿਵੇਂ ਕਿ ਬਾਈਬਲ ਸਾਨੂੰ ਦੱਸਦੀ ਹੈ ਕਿ ਕੁਝ ਪੌਦੇ ਅਤੇ ਕੁਝ ਪਾਣੀ, ਪਰ ਪਰਮੇਸ਼ੁਰ ਵਾਧਾ ਲਿਆਉਂਦਾ ਹੈ (1 ਕੁਰਿੰਥੀਆਂ 3:6-7)।',
      'pl':
          'Przez „nawrócony” mamy na myśli kogoś, kto powiedział Jezusowi „tak”, to znaczy przyjął Jezusa jako swojego Pana i Zbawiciela.\n\nPrzez „nasienie” mamy na myśli osobę, z którą dzieliłeś swoją wiarę, ale nie oddałeś życia Jezusowi. Ale to nie jest strata, jak Biblia mówi nam, że trochę roślin i trochę wody, ale Bóg przynosi wzrost (1 Kor 3:6-7).',
      'pt':
          'Por “converter” estamos nos referindo a alguém que disse sim a Jesus, ou seja, aceitou Jesus como seu Senhor e Salvador.\n\nPor “semente”, estamos nos referindo a alguém com quem você compartilhou sua fé, mas não entregou a vida a Jesus. Mas não é uma perda, como a bíblia nos diz que algumas plantas e algumas regas, mas Deus traz o aumento (1 Co 3:6-7).',
      'ro':
          'Prin „convertiți”, ne referim la cineva care a spus Da lui Isus, adică l-a acceptat pe Isus ca Domn și Mântuitor al vostru.\n\nPrin „sămânță”, ne referim la cineva cu care ți-ai împărtășit credința, dar nu i-ai dat viața lui Isus. Dar nu este o pierdere, după cum biblia ne spune că unele plante și ceva apă, dar Dumnezeu aduce sporul (1 Corinteni 3:6-7).',
      'ru':
          'Под «обращением» мы подразумеваем человека, который сказал Иисусу «да», т. е. принял Иисуса как своего Господа и Спасителя.\n\nПод «семенем» мы подразумеваем человека, с которым вы поделились своей верой, но не отдали свою жизнь Иисусу. Но это не потеря, поскольку Библия говорит нам, что некоторые растения и немного воды, но Бог приносит прирост (1 Кор. 3:6-7).',
      'sd':
          '\"تبديل\" جي ذريعي، اسان ڪنهن ماڻهو ڏانهن اشارو ڪري رهيا آهيون جنهن چيو هو يسوع ڏانهن، يعني، انهن عيسى کي پنهنجو رب ۽ ڇوٽڪارو ڏيندڙ قبول ڪيو.\n\n\"ٻج\" ذريعي، اسان ڪنهن ماڻهو ڏانهن اشارو ڪري رهيا آهيون جنهن سان توهان پنهنجي ايمان سان حصيداري ڪئي پر عيسى کي پنهنجي جان نه ڏني. پر اهو نقصان نه آهي، جيئن بائبل اسان کي ٻڌائي ٿو ته ڪجهه ٻوٽن ۽ ڪجهه پاڻي، پر خدا وڌائي ٿو (1 ڪور 3: 6-7).',
      'si':
          '\"පරිවර්තනය\" යන්නෙන්, අපි යොමු කරන්නේ යේසුස්ට ඔව් යැයි පැවසූ කෙනෙකු වෙතය, එනම් ඔවුන් යේසුස්ව තම ස්වාමියා සහ ගැලවුම්කරුවා ලෙස පිළිගත්තා.\n\n\"බීජ\" යන්නෙන් අපි යොමු කරන්නේ ඔබ ඔබේ ඇදහිල්ල බෙදාගත් නමුත් ඔවුන්ගේ ජීවිතය යේසුස් වහන්සේට නොදුන් කෙනෙකු වෙතය. නමුත් එය පාඩුවක් නොවේ, බයිබලය අපට පවසන පරිදි සමහර ශාක සහ සමහර ජලය, නමුත් දෙවියන් වහන්සේ වැඩි කිරීම ගෙන එයි (1 කොරි 3: 6-7).',
      'sk':
          '„Obrátením“ máme na mysli niekoho, kto povedal Ježišovi áno, t. j. prijal Ježiša ako svojho Pána a Spasiteľa.\n\n„Semeno“ máme na mysli niekoho, s kým ste zdieľali svoju vieru, ale nedali ste svoj život Ježišovi. Ale nie je to strata, ako nám Biblia hovorí, že nejaké rastliny a trochu vody, ale Boh prináša rast (1 Kor 3:6-7).',
      'sl':
          'S »spreobrniti« se nanašamo na nekoga, ki je Jezusu rekel da, kar pomeni, da je Jezusa sprejel za svojega Gospoda in Odrešenika.\n\nS \"semenom\" mislimo na nekoga, s katerim ste delili svojo vero, vendar svojega življenja niste predali Jezusu. Vendar to ni izguba, saj nam sveto pismo pravi, da nekaj rastlin in nekaj vode, ampak Bog prinaša rast (1 Kor 3,6-7).',
      'sq':
          'Me \"konvertim\", ne i referohemi dikujt që i tha po Jezusit, d.m.th., ata e pranuan Jezusin si Zotin dhe Shpëtimtarin e tyre.\n\nMe \"farë\", ne i referohemi dikujt me të cilin ndatë besimin tuaj, por nuk ia dhatë jetën Jezusit. Por kjo nuk është një humbje, siç na thotë Bibla se disa bimë dhe disa ujë, por Zoti sjell rritjen (1 Kor 3:6-7).',
      'sr':
          'Под „преобратити“ мислимо на некога ко је рекао да Исусу, тј. прихватили су Исуса као свог Господа и Спаситеља.\n\nПод „семеном“ мислимо на некога са ким сте делили своју веру, али нисте дали свој живот Исусу. Али то није губитак, као што нам Библија каже да су неке биљке а нешто вода, али Бог доноси повећање (1. Кор. 3:6-7).',
      'sv':
          'Med \"omvända\" syftar vi på någon som sa ja till Jesus, d.v.s. de accepterade Jesus som sin Herre och Frälsare.\n\nMed \"frö\" syftar vi på någon som du delade din tro med men som inte gav sitt liv till Jesus. Men det är inte en förlust, eftersom bibeln säger att vissa växter och lite vatten, men Gud ger ökningen (1 Kor 3:6-7).',
      'ta':
          '\"மாற்றம்\" என்பதன் மூலம், இயேசுவிடம் ஆம் என்று கூறிய ஒருவரைக் குறிப்பிடுகிறோம், அதாவது, அவர்கள் இயேசுவைத் தங்கள் ஆண்டவராகவும் இரட்சகராகவும் ஏற்றுக்கொண்டனர்.\n\n\"விதை\" என்பதன் மூலம், நீங்கள் உங்கள் விசுவாசத்தைப் பகிர்ந்து கொண்ட ஒருவரைக் குறிப்பிடுகிறோம், ஆனால் இயேசுவுக்கு அவர்களின் உயிரைக் கொடுக்கவில்லை. ஆனால் அது ஒரு இழப்பு அல்ல, சில தாவரங்கள் மற்றும் சில தண்ணீர் என்று பைபிள் சொல்கிறது, ஆனால் கடவுள் அதிகரிப்பைக் கொண்டுவருகிறார் (1 கொரி 3:6-7).',
      'tr':
          '\"Dönüştürmek\" derken, İsa\'ya Evet diyen, yani İsa\'yı Rableri ve Kurtarıcıları olarak kabul eden birini kastediyoruz.\n\n\"Tohum\" derken, inancınızı paylaştığınız ancak hayatını İsa\'ya vermediğiniz birinden bahsediyoruz. Ancak İncil\'in bize biraz bitki ve biraz su verdiğini söylediği gibi bu bir kayıp değildir, ancak Tanrı artışı sağlar (1 Korintliler 3:6-7).',
      'uk':
          'Під «навернутими» ми маємо на увазі когось, хто сказав «так» Ісусу, тобто прийняв Ісуса як свого Господа і Спасителя.\n\nПід «насінням» ми маємо на увазі когось, з ким ви розділяли свою віру, але не віддали своє життя Ісусу. Але це не втрата, оскільки Біблія говорить нам, що деякі рослини, а деякі поливають, але Бог приносить приріст (1 Кор. 3:6-7).',
      'ur':
          '\"تبدیل\" کے ذریعے ہم کسی ایسے شخص کی طرف اشارہ کر رہے ہیں جس نے یسوع کو ہاں کہا، یعنی انہوں نے یسوع کو اپنا رب اور نجات دہندہ تسلیم کیا۔\n\n\"بیج\" کے ذریعہ ہم کسی ایسے شخص کا حوالہ دے رہے ہیں جس کے ساتھ آپ نے اپنے ایمان کا اشتراک کیا لیکن اس نے اپنی جان یسوع کو نہیں دی۔ لیکن یہ نقصان نہیں ہے، جیسا کہ بائبل ہمیں بتاتی ہے کہ کچھ پودے اور کچھ پانی، لیکن خدا اضافہ لاتا ہے (1 کور 3: 6-7)۔',
      'uz':
          '\"O\'zgartirish\" deganda biz Isoga \"Ha\" degan odamni nazarda tutyapmiz, ya\'ni ular Isoni Rabbiy va Najotkor sifatida qabul qilganlar.\n\n“Zurriyot” deganda siz imoningiz bilan baham ko\'rgan, lekin o\'z hayotini Isoga bermagan odamni nazarda tutyapmiz. Ammo bu yo\'qotish emas, chunki Bibliyada aytilishicha, ba\'zi o\'simliklar va ba\'zi suvlar, lekin Xudo ko\'paytiradi (1 Korinfliklarga 3:6-7).',
      'vi':
          'Bằng cách \"chuyển đổi\", chúng tôi đang đề cập đến một người đã nói Có với Chúa Giêsu, tức là họ đã chấp nhận Chúa Giêsu là Chúa và Đấng Cứu Rỗi của họ.\n\nKhi dùng từ “hạt giống”, chúng ta đang nói đến người mà bạn đã chia sẻ đức tin nhưng lại không dâng cuộc đời mình cho Chúa Giê-su. Nhưng đó không phải là sự mất mát, như kinh thánh dạy chúng ta rằng một số cây cỏ và một số nước, nhưng Đức Chúa Trời làm cho lớn lên (1 Cô-rinh-tô 3:6-7).',
      'zh_Hans':
          '“皈依者”指的是对耶稣说“是”的人，即他们接受耶稣作为他们的主和救世主。\n\n“种子”指的是你与之分享信仰但没有将生命献给耶稣的人。但这并不是损失，因为圣经告诉我们，有些植物需要水，但上帝会带来增长（哥林多前书 3:6-7）。',
      'zh_Hant':
          '我們所說的「歸信」是指對耶穌說「是」的人，即他們接受耶穌為他們的主和救主。\n\n我們所說的「後裔」是指那些你與之分享信仰但沒有將生命獻給耶穌的人。但這並不是一種損失，正如聖經告訴我們有些植物和有些水，而是神帶來了生長（哥林多前書 3:6-7）。',
    },
